    state LngChargeLowSoc {
        during {
            Pg_req = PL - Ppv - Pw + Pgmax / 5.0;
            Pbd_req = 0.0;
            Pbc_req = Pgmax / 5.0;
            spare_power = 0.0;
            cmd_LNG_cut_in = 1;
            cmd_LNG_cut_out = 0;
            cmd_DG1_cut_in = 0;
            cmd_DG1_cut_out = 1;
            cmd_DG2_cut_in = 0;
            cmd_DG2_cut_out = 1;
            cmd_load_cut_in = 1;
            cmd_load_cut_out = 0;
        }
    }

    state LngDg1ChargeLowSoc {
        during {
            Pg_req = PL - Ppv - Pw + Pd1max / 10.0;
            Pbd_req = 0.0;
            Pbc_req = Pd1max / 10.0;
            spare_power = 0.0;
            cmd_LNG_cut_in = 1;
            cmd_LNG_cut_out = 0;
            cmd_DG1_cut_in = 1;
            cmd_DG1_cut_out = 0;
            cmd_DG2_cut_in = 0;
            cmd_DG2_cut_out = 1;
            cmd_load_cut_in = 1;
            cmd_load_cut_out = 0;
        }
    }

    state LngDg1Dg2ChargeLowSoc {
        during {
            Pg_req = PL - Ppv - Pw + Pd1max / 10.0;
            Pbd_req = 0.0;
            Pbc_req = Pd1max / 10.0;
            spare_power = 0.0;
            cmd_LNG_cut_in = 1;
            cmd_LNG_cut_out = 0;
            cmd_DG1_cut_in = 1;
            cmd_DG1_cut_out = 0;
            cmd_DG2_cut_in = 1;
            cmd_DG2_cut_out = 0;
            cmd_load_cut_in = 1;
            cmd_load_cut_out = 0;
        }
    }

    state OverloadCompletionIllegal {
        during {
            Pg_req = eng3_Pmax + Pd1max + Pd2max;
            Pbd_req = PL - Ppv - Pw - eng3_Pmax - Pd1max - Pd2max;
            Pbc_req = 0.0;
            spare_power = 0.0;
            cmd_LNG_cut_in = 1;
            cmd_LNG_cut_out = 0;
            cmd_DG1_cut_in = 1;
            cmd_DG1_cut_out = 0;
            cmd_DG2_cut_in = 1;
            cmd_DG2_cut_out = 0;
            cmd_load_cut_in = 1;
            cmd_load_cut_out = 0;
        }
    }
}
